// Demo response generator. Produces clearly-labeled simulated replies so users
// always know they are NOT from a real AI model. Used as a graceful fallback
// when the OpenAI API key is not configured or the API is unavailable.

const TEMPLATES = [
  "This is a simulated demo response — not generated by a real AI model. In demo mode, Nexora AI echoes a friendly placeholder so you can explore the interface. To get real, intelligent answers, add an OPENAI_API_KEY environment variable on the server.",
  "Demo mode is active: this message is a placeholder, not a real AI reply. Once an OpenAI API key is configured server-side, your questions will be answered by the live model.",
  "You're seeing a simulated response because the OpenAI API isn't configured yet. This lets you try the chat experience without a key. Add OPENAI_API_KEY to enable real AI answers.",
  "Placeholder reply from demo mode — no AI model was contacted. Configure OPENAI_API_KEY on the server to switch to genuine model responses.",
];

const FOLLOWUPS = [
  "Try asking about a topic you're curious about, or describe a task you'd like help with.",
  "Feel free to continue the conversation — your messages will still appear here once live mode is enabled.",
  "You can also clear this chat with the button above and start a fresh conversation.",
  "The sidebar keeps your chat history locally in your browser, even in demo mode.",
];

export function generateDemoReply(userText: string): string {
  const trimmed = userText.trim();
  const template = TEMPLATES[Math.floor(Math.random() * TEMPLATES.length)];
  const followup = FOLLOWUPS[Math.floor(Math.random() * FOLLOWUPS.length)];

  const preview =
    trimmed.length > 120 ? `${trimmed.slice(0, 120)}…` : trimmed;

  return `${template}\n\nYou said: "${preview}".\n\n${followup}`;
}

export function isDemoMode(): boolean {
  // Server-side only. Never expose the key itself.
  return !process.env.OPENAI_API_KEY;
}
